import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { FiPlus, FiEdit2, FiTrash2, FiEye } from 'react-icons/fi';
import api from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const AdminEvents = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingEvent, setEditingEvent] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    date: '',
    location: '',
    is_upcoming: true,
    is_past: false,
  });
  const [imageFile, setImageFile] = useState(null);

  useEffect(() => {
    fetchEvents();
  }, []);

  const fetchEvents = async () => {
    try {
      const response = await api.get('/api/events/');
      setEvents(response.data);
    } catch (error) {
      toast.error('Failed to load events');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const payload = new FormData();
      payload.append('title', formData.title || '');
      payload.append('description', formData.description || '');
      payload.append('date', formData.date || '');
      payload.append('location', formData.location || '');
      payload.append('is_upcoming', String(formData.is_upcoming));
      payload.append('is_past', String(formData.is_past));
      if (imageFile) {
        payload.append('image_file', imageFile);
      }

      if (editingEvent) {
        await api.put(`/api/events/${editingEvent.id}`, payload, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('Event updated successfully');
      } else {
        await api.post('/api/events/', payload, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('Event created successfully');
      }
      setModalOpen(false);
      setEditingEvent(null);
      setFormData({
        title: '',
        description: '',
        date: '',
        location: '',
        is_upcoming: true,
        is_past: false,
      });
      setImageFile(null);
      fetchEvents();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Operation failed');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this event?')) {
      try {
        await api.delete(`/api/events/${id}`);
        toast.success('Event deleted successfully');
        fetchEvents();
      } catch (error) {
        toast.error('Failed to delete event');
      }
    }
  };

  const handleEdit = (event) => {
    setEditingEvent(event);
    setFormData({
      title: event.title,
      description: event.description || '',
      date: event.date.slice(0, 16),
      location: event.location || '',
      is_upcoming: event.is_upcoming,
      is_past: event.is_past,
    });
    setImageFile(null);
    setModalOpen(true);
  };

  const columns = [
    { key: 'title', label: 'Title' },
    { key: 'date', label: 'Date', render: (val) => new Date(val).toLocaleDateString() },
    { key: 'location', label: 'Location' },
    {
      key: 'is_upcoming',
      label: 'Status',
      render: (val) => (
        <span className={`px-2 py-1 rounded-full text-xs ${
          val ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
        }`}>
          {val ? 'Upcoming' : 'Past'}
        </span>
      ),
    },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button
            onClick={() => handleEdit(row)}
            className="text-blue-600 hover:text-blue-800"
          >
            <FiEdit2 />
          </button>
          <button
            onClick={() => handleDelete(row.id)}
            className="text-red-600 hover:text-red-800"
          >
            <FiTrash2 />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Events Management</h1>
        <button
          onClick={() => {
            setEditingEvent(null);
            setFormData({
              title: '',
              description: '',
              date: '',
              location: '',
              is_upcoming: true,
              is_past: false,
            });
            setImageFile(null);
            setModalOpen(true);
          }}
          className="admin-btn-primary flex items-center space-x-2"
        >
          <FiPlus />
          <span>Add Event</span>
        </button>
      </div>

      <AdminCard>
        <AdminTable
          columns={columns}
          data={events}
          loading={loading}
        />
      </AdminCard>

      <AdminModal
        isOpen={modalOpen}
        onClose={() => {
          setModalOpen(false);
          setEditingEvent(null);
        }}
        title={editingEvent ? 'Edit Event' : 'Create Event'}
      >
        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label className="admin-label">Title *</label>
              <input
                type="text"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="admin-input"
                rows="3"
              />
            </div>
            <div>
              <label className="admin-label">Date & Time *</label>
              <input
                type="datetime-local"
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Location</label>
              <input
                type="text"
                value={formData.location}
                onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                className="admin-input"
              />
            </div>
            <div>
              <label className="admin-label">{editingEvent ? 'Upload New Image (optional)' : 'Upload Image'}</label>
              <input
                type="file"
                accept="image/*"
                onChange={(e) => setImageFile(e.target.files?.[0] || null)}
                className="admin-input"
              />
              {editingEvent && imageFile == null && (
                <p className="text-xs text-gray-500 mt-1">Leave empty to keep current image.</p>
              )}
            </div>
            <div className="flex space-x-4">
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={formData.is_upcoming}
                  onChange={(e) => setFormData({ ...formData, is_upcoming: e.target.checked })}
                />
                <span>Upcoming</span>
              </label>
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={formData.is_past}
                  onChange={(e) => setFormData({ ...formData, is_past: e.target.checked })}
                />
                <span>Past</span>
              </label>
            </div>
          </div>
          <div className="mt-6 flex justify-end space-x-3">
            <button
              type="button"
              onClick={() => {
                setModalOpen(false);
                setEditingEvent(null);
              }}
              className="admin-btn-secondary"
            >
              Cancel
            </button>
            <button type="submit" className="admin-btn-primary">
              {editingEvent ? 'Update' : 'Create'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminEvents;
